// Themenliste fuer das taegliche Monitoring.
// Jeder Eintrag wird ein eigenes Item -> die Schleife laeuft einmal pro Thema.

const MAX_PER_RUN = 5;        // HARTE KOSTENBREMSE: max. Themen pro Lauf
const TIMEFRAME = 'month';     // taeglich laufen, Wochenfenster gegen Luecken

const watchlist = [
  { topic: 'Adyen',             kind: 'company' },
  { topic: 'Stripe',            kind: 'company' },
  { topic: 'Visa',              kind: 'company' },
  { topic: 'digital euro',      kind: 'topic'   },
  { topic: 'agentic payments',  kind: 'topic'   }
];

const selected = watchlist.slice(0, MAX_PER_RUN);

return selected.map((w, i) => ({
  json: {
    topic: w.topic,
    kind: w.kind,
    timeframe: TIMEFRAME,
    position: i + 1,
    total: selected.length,
    runId: new Date().toISOString()
  }
}));

// Zusammenfassung des Monitoring-Laufs.

const results = $input.all().map(i => i.json || {});

const total = results.length;
const newBriefs = results.filter(r => r.was_new === true);
const skipped = results.filter(r => r.skipped === true);
const duplicates = results.filter(r => r.was_new === false && r.skipped !== true);
const failed = results.filter(r => !r.content_hash && r.skipped !== true);

const sourcesWritten = results.reduce((s, r) => s + (r.sources_written || 0), 0);
const sourcesSeen = results.reduce((s, r) => s + (r.source_count || 0), 0);

// Nach Impact sortiert, damit das Wichtigste oben steht
const ranked = newBriefs
  .filter(r => typeof r.impact_score === 'number')
  .sort((a, b) => b.impact_score - a.impact_score);

const lines = ranked.map(r =>
  `  [${r.impact_score}/${r.confidence_score}] ${r.topic}: ${r.headline || '(kein Headline)'}`
);

const summary = [
  `Payments Monitor — ${new Date().toISOString().slice(0, 16).replace('T', ' ')}`,
  ``,
  `Themen verarbeitet: ${total}`,
  `Neue Briefs:        ${newBriefs.length}`,
  `Duplikate:          ${duplicates.length}`,
  `Zu schwach:         ${skipped.length}`,
  `Fehlgeschlagen:     ${failed.length}`,
  `Quellen gesichtet:  ${sourcesSeen}`,
  `Quellen gespeichert:${sourcesWritten}`,
  ``,
  newBriefs.length ? `Neue Entwicklungen (impact/confidence):` : `Keine neuen Entwicklungen.`,
  ...lines,
  ``,
  failed.length ? `Fehlgeschlagene Themen: ${failed.map(f => f.topic || '?').join(', ')}` : ''
].filter(Boolean).join('\n');

return [{
  json: {
    run_finished_at: new Date().toISOString(),
    topics_processed: total,
    new_briefs: newBriefs.length,
    duplicates: duplicates.length,
    skipped: skipped.length,
    failed: failed.length,
    sources_seen: sourcesSeen,
    sources_written: sourcesWritten,
    estimated_cost_usd: Number((total * 0.05).toFixed(2)),
    summary_text: summary,
    results
  }
}];
